declare(strict_types=1);

namespace JBZoo\CsvBlueprint\Data;

/**
 * Read-only lookups over the cloud reference data in this directory.
 * The JSON files are generated by scripts/update-cloud-data.php from the providers' public feeds.
 */
final class CloudData
{
    public const AZURE_SERVICE_TAGS = __DIR__ . '/azure-service-tags.json';
    public const AWS_REGIONS = __DIR__ . '/aws-regions.json';

    /** @var array<string, array<string, mixed>> */
    private static array $cache = [];

    /**
     * @return null|string[] the network features of the service tag (case-insensitive), or null if it doesn't exist
     */
    public static function azureServiceTagFeatures(string $tag): ?array
    {
        $tags = self::lowerKeys(self::AZURE_SERVICE_TAGS, 'tags');

        return $tags[\strtolower($tag)] ?? null;
    }

    /**
     * Whether the region code (case-sensitive, like "eu-west-2") is in AWS's published IP ranges.
     */
    public static function isAwsRegion(string $region): bool
    {
        return \in_array($region, self::list(self::AWS_REGIONS, 'regions'), true);
    }

    /**
     * @return string[]
     */
    public static function azureServiceTags(): array
    {
        return \array_map('strval', \array_keys(self::list(self::AZURE_SERVICE_TAGS, 'tags')));
    }

    /**
     * @return string[]
     */
    public static function awsRegions(): array
    {
        return self::list(self::AWS_REGIONS, 'regions');
    }

    /**
     * The closest candidate within two edits (case-insensitive), to suggest a fix for a typo.
     * @param string[] $candidates
     */
    public static function closest(string $value, array $candidates): ?string
    {
        $value = \strtolower($value);
        $best = null;
        $bestDistance = 3;

        foreach ($candidates as $candidate) {
            $distance = \levenshtein($value, \strtolower($candidate));
            if ($distance < $bestDistance) {
                [$best, $bestDistance] = [$candidate, $distance];
            }
        }

        return $best;
    }

    private static function load(string $path): array
    {
        if (!isset(self::$cache[$path])) {
            $json = \file_get_contents($path);
            if ($json === false) {
                throw new \RuntimeException("Cloud data file is missing: {$path}");
            }

            self::$cache[$path] = (array)\json_decode($json, true, 8, \JSON_THROW_ON_ERROR);
        }

        return self::$cache[$path];
    }

    private static function list(string $path, string $key): array
    {
        return (array)(self::load($path)[$key] ?? []);
    }

    private static function lowerKeys(string $path, string $key): array
    {
        $cacheKey = "{$path}#lower-{$key}";
        if (!isset(self::$cache[$cacheKey])) {
            self::$cache[$cacheKey] = \array_change_key_case(self::list($path, $key), \CASE_LOWER);
        }

        return self::$cache[$cacheKey];
    }
}
